const technologyCards: TechnologyCard[] = technologyStacks.flatMap((group) =>
  group.items.map((item) => ({
    category: group.category,
    name: item.name,
    iconSvg: item.iconSvg,
    iconAlt: item.iconAlt,
  })),
)

const containerVariants: Variants = {
  hidden: {},
  show: {
    transition: {
      duration: 0.2,
      staggerChildren: 0.02,
    },
  },
}

const cardVariants: Variants = {
  hidden: { opacity: 0, y: 12 },
  show: { opacity: 1, y: 0 },
}

const TechnologyCardItem = memo(function TechnologyCardItem({ category, name, iconSvg, iconAlt }: TechnologyCard) {
  return (
    <motion.div
      variants={cardVariants}
      whileHover={{ y: -4, scale: 1.01 }}
      transition={{ duration: 0.2, ease: 'easeOut' }}
      className="group h-full cursor-pointer"
    >
      <Card className="relative flex h-full min-h-[160px] items-center justify-center overflow-hidden rounded-[28px] border border-border/70 bg-card/75 px-4 py-5 text-center shadow-[0_18px_45px_rgba(15,23,42,0.12)] backdrop-blur-xl transition duration-200 ease-out">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_top,rgba(59,130,246,0.16),transparent_60%),radial-gradient(circle_at_bottom,rgba(168,85,247,0.14),transparent_55%)] opacity-0 transition-opacity duration-200 group-hover:opacity-100" />
        <div className="absolute inset-0 rounded-[inherit] border border-transparent bg-[linear-gradient(120deg,rgba(59,130,246,0.24),rgba(168,85,247,0.18))] opacity-0 transition-opacity duration-200 group-hover:opacity-100" />

        <div className="relative flex flex-col items-center gap-3">
          <div className="flex size-14 items-center justify-center rounded-2xl border border-border/70 bg-background/70 shadow-inner transition duration-200 group-hover:scale-105 group-hover:border-brand-blue/35 group-hover:bg-background/90">
            <SkillLogo svg={iconSvg} alt={iconAlt} className="size-8 object-contain transition-transform duration-200 group-hover:scale-105" />
          </div>

          <div className="space-y-1.5">
            <p className="font-mono text-[10px] uppercase tracking-[0.26em] text-muted-foreground">
              {category}
            </p>
            <h3 className="text-balance text-[0.92rem] font-semibold leading-tight text-foreground sm:text-sm">
              {name}
            </h3>
          </div>
        </div>
      </Card>
    </motion.div>
  )
})

export function Skills() {
  const prefersReducedMotion = useReducedMotion()
  const cards = useMemo(() => technologyCards, [])

  return (
    <section id="skills" className="relative overflow-hidden px-4 py-24 sm:px-6">
      <div className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-80 mesh-gradient opacity-30 blur-3xl" />
      <div className="mx-auto max-w-7xl">
        <motion.div
          className="mx-auto max-w-2xl text-center"
          initial={prefersReducedMotion ? false : { opacity: 0, y: 24 }}
          whileInView={prefersReducedMotion ? undefined : { opacity: 1, y: 0 }}
          viewport={{ once: true, margin: '-80px' }}
          transition={{ duration: 0.4, ease: [0.21, 0.47, 0.32, 0.98] }}
        >
          <span className="font-mono text-xs uppercase tracking-[0.2em] text-brand-blue">
            SKILLS
          </span>
          <h2 className="mt-3 text-balance text-3xl font-semibold tracking-tight sm:text-4xl">
            Technologies I Work With
          </h2>
          <p className="mt-4 text-pretty leading-relaxed text-muted-foreground">
            A collection of technologies, tools, cloud platforms, and frameworks I use to build scalable automation, infrastructure, and DevOps solutions.
          </p>
        </motion.div>

        <motion.div
          className="mt-14 grid gap-4 sm:grid-cols-2 md:grid-cols-4 lg:grid-cols-6"
          variants={containerVariants}
          initial={prefersReducedMotion ? false : 'hidden'}
          whileInView={prefersReducedMotion ? undefined : 'show'}
          viewport={{ once: true, amount: 0.1 }}
        >
          {cards.map((card) => (
            <TechnologyCardItem
              key={`${card.category}-${card.name}`}
              category={card.category}
              name={card.name}
              iconSvg={card.iconSvg}
              iconAlt={card.iconAlt}
            />
          ))}
        </motion.div>

        <p className="mt-10 text-center text-sm text-muted-foreground">
          Always learning new technologies to build better software.
        </p>
      </div>
    </section>
  )
}
